import React, { useRef, useEffect } from 'react';
import { motion } from 'framer-motion';

interface TypingAreaProps {
  targetText: string;
  currentIndex: number;
  isError: boolean;
  onInput: (char: string, code: string) => void;
  onBlur: () => void;
  onFocus: () => void;
}

export const TypingArea: React.FC<TypingAreaProps> = ({ 
  targetText, 
  currentIndex, 
  isError, 
  onInput,
  onBlur,
  onFocus
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Keep focus on the hidden input
  useEffect(() => {
    const focusInput = () => inputRef.current?.focus();
    const handleClick = () => focusInput();

    // Initial focus
    focusInput();

    // Re-focus when user clicks anywhere in the typing area
    const container = containerRef.current;
    container?.addEventListener('click', handleClick);

    return () => container?.removeEventListener('click', handleClick);
  }, []);

  // Sync scroll to cursor if text is long
  useEffect(() => {
    const activeElement = document.getElementById(`char-${currentIndex}`);
    if (activeElement && containerRef.current) {
        // Simple scroll into view logic if needed for long texts
        // activeElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [currentIndex]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // Prevent default browser actions for keys that might disrupt flow (like standard browser shortcuts if necessary)
    // But allow Tab to blur if user wants to leave.
    // e.preventDefault(); 

    // We only care about the key press.
    // Use e.key for the character, e.code for the physical location
    onInput(e.key, e.code);
  };

  return (
    <div 
      ref={containerRef}
      className="relative w-full max-w-4xl mx-auto mb-8 cursor-text group"
    >
      {/* 
        The Hidden Input 
        - Opacity 0 to be invisible but receive events.
        - Absolute positioned to not affect layout.
        - Controlled input but we manually clear value to ensure fresh events.
      */}
      <input
        ref={inputRef}
        type="text"
        className="absolute inset-0 opacity-0 z-0 cursor-default"
        autoComplete="off"
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck="false"
        onKeyDown={handleKeyDown}
        onBlur={onBlur}
        onFocus={onFocus}
        // Use an empty value to force the input to always be "ready"
        // We track state in React, not the input value
        value="" 
        onChange={() => {}} // No-op, handled by onKeyDown
      />

      {/* Visual Display Container */}
      <div 
        className={`
          bg-slate-800 rounded-2xl p-8 sm:p-12 shadow-inner border-2 min-h-[160px]
          flex flex-wrap content-start leading-relaxed text-3xl sm:text-4xl font-medium
          transition-colors duration-200
          ${isError ? 'border-red-500/50 bg-red-900/10' : 'border-slate-700 group-focus-within:border-emerald-500/50'}
        `}
        dir="rtl" // CRITICAL: RTL for Arabic flow
      >
        {targetText.split('').map((char, index) => {
          let colorClass = 'text-slate-500'; // Default: Future text

          if (index < currentIndex) {
            colorClass = 'text-emerald-400'; // Past: Correct
          } else if (index === currentIndex) {
            colorClass = isError ? 'text-red-400' : 'text-slate-100'; // Current
          }

          const isCurrent = index === currentIndex;

          return (
            <div key={index} className="relative inline-flex flex-col items-center justify-center h-12 min-w-[14px]">
              {/* Character */}
              <span 
                id={`char-${index}`}
                className={`${colorClass} transition-colors duration-75 px-0.5 whitespace-pre`}
              >
                {char}
              </span>

              {/* Cursor - Framer Motion for smooth movement */}
              {isCurrent && (
                <motion.div
                  layoutId="cursor"
                  className={`absolute -bottom-1 h-1 w-full rounded-full ${isError ? 'bg-red-500' : 'bg-emerald-400'}`}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: [1, 0.5, 1] }}
                  transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                />
              )}
            </div>
          );
        })}
      </div>

      {/* Click to focus overlay (if lost focus) */}
      <div className="absolute top-2 left-2 text-xs text-slate-500 opacity-0 group-focus-within:opacity-0 transition-opacity duration-200 pointer-events-none">
        Click to focus
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { ARABIC_KEY_MAP, LESSONS } from './constants';
import { Lesson, TypingStats } from './types';
import { VirtualKeyboard } from './components/VirtualKeyboard';
import { TypingArea } from './components/TypingArea';
import { Stats } from './components/Stats';
import { BookOpen, RefreshCw, Keyboard, CheckCircle2 } from 'lucide-react';

const App: React.FC = () => {
  // --- State ---
  const [currentLesson, setCurrentLesson] = useState<Lesson>(LESSONS[0]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isError, setIsError] = useState(false);
  const [pressedKey, setPressedKey] = useState<string | null>(null);

  // Stats State
  const [startTime, setStartTime] = useState<number | null>(null);
  const [correctCharCount, setCorrectCharCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [isFocused, setIsFocused] = useState(true);

  // --- Derived State ---
  const isLessonComplete = currentIndex >= currentLesson.text.length;

  const stats: TypingStats = useMemo(() => {
    const totalTyped = correctCharCount + errorCount;
    const accuracy = totalTyped > 0 ? (correctCharCount / totalTyped) * 100 : 100;

    let wpm = 0;
    if (startTime && totalTyped > 0) {
      const timeElapsedMinutes = (Date.now() - startTime) / 60000;
      // Standard WPM calculation: (All characters / 5) / minutes
      wpm = (correctCharCount / 5) / timeElapsedMinutes;
    }

    return {
      wpm: wpm || 0,
      accuracy,
      correctChars: correctCharCount,
      totalChars: currentLesson.text.length,
      startTime
    };
  }, [correctCharCount, errorCount, startTime, currentLesson.text.length]);

  // --- Handlers ---

  const resetLesson = useCallback(() => {
    setCurrentIndex(0);
    setIsError(false);
    setStartTime(null);
    setCorrectCharCount(0);
    setErrorCount(0);
    setPressedKey(null);
  }, []);

  const changeLesson = (lessonId: number) => {
    const lesson = LESSONS.find(l => l.id === lessonId) || LESSONS[0];
    setCurrentLesson(lesson);
    resetLesson();
  };

  const handleInput = useCallback((key: string, code: string) => {
    if (isLessonComplete) return;

    // Start timer on first input
    if (startTime === null) {
      setStartTime(Date.now());
    }

    // Determine the typed character
    // Priority 1: Direct key value if it's Arabic (User has Arabic Keyboard)
    // Priority 2: Mapping from physical key code (User has English Keyboard)
    let typedChar = key;
    const mapped = ARABIC_KEY_MAP[code];

    // Simple heuristic: if the key produced is a standard ASCII char but we expect Arabic,
    // try to use the mapped Arabic char.
    const targetChar = currentLesson.text[currentIndex];

    // Check if the physical key matches the target (Teaching layout)
    // OR if the produced character matches the target (Using native layout)
    const isPhysicalMatch = mapped?.char === targetChar;
    const isLiteralMatch = key === targetChar;

    setPressedKey(code); // For visual feedback

    if (isPhysicalMatch || isLiteralMatch) {
      // Correct
      setIsError(false);
      setCorrectCharCount(prev => prev + 1);
      setCurrentIndex(prev => prev + 1);
    } else {
      // Ignore modifier keys from counting as errors
      if (['Shift', 'Alt', 'Control', 'CapsLock', 'Tab'].includes(key)) return;

      // Incorrect
      setIsError(true);
      setErrorCount(prev => prev + 1);

      // Flash error state timeout
      setTimeout(() => setIsError(false), 200);
    }
  }, [currentIndex, currentLesson, isLessonComplete, startTime]);

  // Clear pressed key visualization on key up
  useEffect(() => {
    const handleKeyUp = () => setPressedKey(null);
    window.addEventListener('keyup', handleKeyUp);
    return () => window.removeEventListener('keyup', handleKeyUp);
  }, []);

  // --- Render ---

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex flex-col font-sans">

      {/* Header */}
      <header className="bg-slate-800 border-b border-slate-700 p-4">
        <div className="max-w-6xl mx-auto flex justify-between items-center" dir="rtl">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-600 p-2 rounded-lg">
              <Keyboard className="text-white" size={24} />
            </div>
            <h1 className="text-2xl font-bold text-white">المعلم <span className="text-emerald-500 text-lg font-normal mx-2">Typing Tutor</span></h1>
          </div>

          <div className="flex gap-2">
             <select 
               className="bg-slate-700 text-slate-200 border border-slate-600 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
               value={currentLesson.id}
               onChange={(e) => changeLesson(Number(e.target.value))}
             >
               {LESSONS.map(l => (
                 <option key={l.id} value={l.id}>{l.title}</option>
               ))}
             </select>
             <button 
               onClick={resetLesson}
               className="p-2 bg-slate-700 hover:bg-slate-600 rounded-lg transition-colors text-slate-300"
               title="Reset Lesson"
             >
               <RefreshCw size={20} />
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow flex flex-col items-center justify-start pt-8 pb-12 px-4">

        {/* Lesson Info */}
        <div className="text-center mb-8 max-w-2xl" dir="rtl">
          <h2 className="text-3xl font-bold mb-2 text-white">{currentLesson.title}</h2>
          <p className="text-slate-400">{currentLesson.description}</p>
        </div>

        {isLessonComplete ? (
          <div className="bg-slate-800 border border-slate-700 rounded-2xl p-8 sm:p-12 text-center max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
             <div className="mx-auto bg-emerald-500/20 w-20 h-20 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 size={48} className="text-emerald-500" />
             </div>
             <h3 className="text-2xl font-bold text-white mb-2">Lesson Complete! | أحسنت</h3>
             <p className="text-slate-400 mb-6">Great job. Here is how you performed:</p>

             <div className="grid grid-cols-2 gap-4 mb-8" dir="rtl">
               <div className="bg-slate-700/50 p-4 rounded-xl">
                 <div className="text-sm text-slate-400">سرعة (WPM)</div>
                 <div className="text-2xl font-bold text-emerald-400">{Math.round(stats.wpm)}</div>
               </div>
               <div className="bg-slate-700/50 p-4 rounded-xl">
                 <div className="text-sm text-slate-400">دقة (Accuracy)</div>
                 <div className="text-2xl font-bold text-blue-400">{Math.round(stats.accuracy)}%</div>
               </div>
             </div>

             <div className="flex gap-4 justify-center">
               <button 
                onClick={resetLesson}
                className="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-medium transition-colors"
               >
                 إعادة (Retry)
               </button>
               <button 
                 onClick={() => {
                    const next = LESSONS.find(l => l.id === currentLesson.id + 1);
                    if (next) changeLesson(next.id);
                 }}
                 disabled={!LESSONS.find(l => l.id === currentLesson.id + 1)}
                 className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
               >
                 التالي (Next Lesson)
               </button>
             </div>
          </div>
        ) : (
          <>
            <Stats stats={stats} />

            <div className="w-full max-w-4xl relative">
              {!isFocused && (
                 <div className="absolute -top-8 left-0 right-0 text-center text-amber-500 text-sm font-medium animate-pulse">
                   ⚠️ Focus lost. Click the box to continue typing.
                 </div>
              )}

              <TypingArea 
                targetText={currentLesson.text}
                currentIndex={currentIndex}
                isError={isError}
                onInput={handleInput}
                onBlur={() => setIsFocused(false)}
                onFocus={() => setIsFocused(true)}
              />
            </div>

            <VirtualKeyboard 
              activeChar={currentLesson.text[currentIndex]}
              pressedKey={pressedKey}
              isError={isError}
            />
          </>
        )}

      </main>

      {/* Footer */}
      <footer className="py-6 text-center text-slate-500 text-sm border-t border-slate-800">
        <p>Supports Standard Arabic 101 Layout • English Keyboard Compatible</p>
      </footer>

    </div>
  );
};

export default App;

