    let wpm = 0;
    if (startTime && totalTyped > 0) {
      const timeElapsedMinutes = (Date.now() - startTime) / 60000;
      wpm = (correctCharCount / 5) / timeElapsedMinutes;
    }

    return {
      wpm: wpm || 0,
      accuracy,
      correctChars: correctCharCount,
      totalChars: currentLesson.text.length,
      startTime
    };
  }, [correctCharCount, errorCount, startTime, currentLesson.text.length]);

  // --- Handlers ---

  const resetLesson = useCallback(() => {
    setCurrentIndex(0);
    setIsError(false);
    setStartTime(null);
    setCorrectCharCount(0);
    setErrorCount(0);
    setPressedKey(null);
  }, []);

  const changeLesson = (lessonId: number) => {
    const lesson = LESSONS.find(l => l.id === lessonId) || LESSONS[0];
    setCurrentLesson(lesson);
    resetLesson();
  };

  const toggleZenMode = () => setIsZenMode(prev => !prev);

  // Zen Mode Escape Listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isZenMode) {
        setIsZenMode(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isZenMode]);

  const handleInput = useCallback((key: string, code: string) => {
    if (isLessonComplete) return;

    if (startTime === null) setStartTime(Date.now());

    const mapped = ARABIC_KEY_MAP[code];
    const targetChar = currentLesson.text[currentIndex];
    const isPhysicalMatch = mapped?.char === targetChar;
    const isLiteralMatch = key === targetChar;

    setPressedKey(code);

    if (isPhysicalMatch || isLiteralMatch) {
      setIsError(false);
      setCorrectCharCount(prev => prev + 1);
      setCurrentIndex(prev => prev + 1);
    } else {
      if (['Shift', 'Alt', 'Control', 'CapsLock', 'Tab', 'Escape'].includes(key)) return;
      setIsError(true);
      setErrorCount(prev => prev + 1);
      setTimeout(() => setIsError(false), 200);
    }
  }, [currentIndex, currentLesson, isLessonComplete, startTime]);

  useEffect(() => {
    const handleKeyUp = () => setPressedKey(null);
    window.addEventListener('keyup', handleKeyUp);
    return () => window.removeEventListener('keyup', handleKeyUp);
  }, []);

  // --- Render ---

  return (
    <div className={`min-h-screen bg-slate-900 text-slate-100 flex flex-col font-sans transition-all duration-500 ${isZenMode ? 'justify-center' : ''}`}>

      {/* Header */}
      {!isZenMode && (
        <header className="bg-slate-800 border-b border-slate-700 p-4 transition-all">
          <div className="max-w-6xl mx-auto flex justify-between items-center" dir="rtl">
            <div className="flex items-center gap-3">
              <div className="bg-emerald-600 p-2 rounded-lg">
                <Keyboard className="text-white" size={24} />
              </div>
              <h1 className="text-2xl font-bold text-white">المعلم <span className="text-emerald-500 text-lg font-normal mx-2">Typing Tutor</span></h1>
            </div>

            <div className="flex gap-2 items-center">
              <button 
                 onClick={toggleZenMode}
                 className="flex items-center gap-2 px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg transition-colors text-slate-300 text-sm mx-2"
                 title="Enter Zen Mode"
               >
                 <Maximize2 size={16} />
                 <span className="hidden sm:inline">Zen Mode</span>
               </button>

               <select 
                 className="bg-slate-700 text-slate-200 border border-slate-600 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                 value={currentLesson.id}
                 onChange={(e) => changeLesson(Number(e.target.value))}
               >
                 {LESSONS.map(l => (
                   <option key={l.id} value={l.id}>{l.title}</option>
                 ))}
               </select>
               <button 
                 onClick={resetLesson}
                 className="p-2 bg-slate-700 hover:bg-slate-600 rounded-lg transition-colors text-slate-300"
                 title="Reset Lesson"
               >
                 <RefreshCw size={20} />
               </button>
            </div>
          </div>
        </header>
      )}

      {/* Main Content */}
      <main className={`flex-grow flex flex-col items-center ${isZenMode ? 'justify-center' : 'justify-start pt-8 pb-12'} px-4`}>

        {/* Zen Mode Exit Hint */}
        {isZenMode && (
           <div className="fixed top-6 right-6 text-slate-600 text-sm animate-pulse">
             Press ESC to exit
           </div>
        )}

        {/* Lesson Info */}
        {!isZenMode && (
          <div className="text-center mb-8 max-w-2xl" dir="rtl">
            <h2 className="text-3xl font-bold mb-2 text-white">{currentLesson.title}</h2>
            <p className="text-slate-400">{currentLesson.description}</p>
          </div>
        )}

        {isLessonComplete ? (
          <div className="bg-slate-800 border border-slate-700 rounded-2xl p-8 sm:p-12 text-center max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
             <div className="mx-auto bg-emerald-500/20 w-20 h-20 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 size={48} className="text-emerald-500" />
             </div>
             <h3 className="text-2xl font-bold text-white mb-2">Lesson Complete! | أحسنت</h3>
             <p className="text-slate-400 mb-6">Great job. Here is how you performed:</p>

             <div className="grid grid-cols-2 gap-4 mb-8" dir="rtl">
               <div className="bg-slate-700/50 p-4 rounded-xl">
                 <div className="text-sm text-slate-400">سرعة (WPM)</div>
                 <div className="text-2xl font-bold text-emerald-400">{Math.round(stats.wpm)}</div>
               </div>
               <div className="bg-slate-700/50 p-4 rounded-xl">
                 <div className="text-sm text-slate-400">دقة (Accuracy)</div>
                 <div className="text-2xl font-bold text-blue-400">{Math.round(stats.accuracy)}%</div>
               </div>
             </div>

             <div className="flex gap-4 justify-center">
               <button 
                onClick={resetLesson}
                className="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-medium transition-colors"
               >
                 إعادة (Retry)
               </button>
               <button 
                 onClick={() => {
                    const next = LESSONS.find(l => l.id === currentLesson.id + 1);
                    if (next) changeLesson(next.id);
                 }}
                 disabled={!LESSONS.find(l => l.id === currentLesson.id + 1)}
                 className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
               >
                 التالي (Next Lesson)
               </button>
             </div>
          </div>
        ) : (
          <>
            {!isZenMode && <Stats stats={stats} />}

            <div className={`w-full relative ${isZenMode ? 'max-w-6xl' : 'max-w-4xl'}`}>
              {!isFocused && !isZenMode && (
                 <div className="absolute -top-8 left-0 right-0 text-center text-amber-500 text-sm font-medium animate-pulse">
                   ⚠️ Focus lost. Click the box to continue typing.
                 </div>
              )}

              <TypingArea 
                targetText={currentLesson.text}
                currentIndex={currentIndex}
                isError={isError}
                onInput={handleInput}
                onBlur={() => setIsFocused(false)}
                onFocus={() => setIsFocused(true)}
                isZenMode={isZenMode}
              />
            </div>

            {!isZenMode && (
              <VirtualKeyboard 
                activeChar={currentLesson.text[currentIndex]}
                pressedKey={pressedKey}
                isError={isError}
              />
            )}
          </>
        )}

      </main>

      {/* Footer */}
      {!isZenMode && (
        <footer className="py-6 text-center text-slate-500 text-sm border-t border-slate-800">
          <p>Supports Standard Arabic 101 Layout • English Keyboard Compatible</p>
        </footer>
      )}

    </div>
  );
};

